<?php
declare(strict_types=1);namespace App\Controllers;use App\Core\Database;use App\Core\Request;
final class DashboardController extends BaseController {public function index(Request $r):void{$this->auth();$this->require('dashboard.view');$pdo=Database::connection();$stats=[];foreach(['purchase_requests'=>'Purchase requests','requisitions'=>'Requisitions','vendors'=>'Vendors','purchase_orders'=>'Purchase orders','deliveries'=>'Deliveries','invoices'=>'Invoices','payments'=>'Payments'] as $t=>$label){$stats[]=['label'=>$label,'count'=>(int)$pdo->query('SELECT COUNT(*) FROM `'.$t.'`')->fetchColumn()];}$recent=$pdo->query('SELECT po_number,currency_code,total_amount,status,order_date FROM purchase_orders ORDER BY id DESC LIMIT 8')->fetchAll();$this->view('dashboard.index',['stats'=>$stats,'recent'=>$recent]);}}
